+static void dump_code(int indent, struct bytecode* bc) {
+  int pc = 0;
+  if (jq_active) {
+    jq_active->dump_indent = indent;
+    jq_active->dump_pc = 0;
+    jq_active->dump_codeptr = bc->code;
+  }
+  while (pc < bc->codelen) {
+    printf("%*s", indent, "");
+    dump_operation(bc, bc->code + pc);
+    printf("\n");
+    pc += bytecode_operation_length(bc->code + pc);
+  }
+}
